package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Predicate;

import org.eclipse.rdf4j.common.iteration.Iterations;
import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.NotifyingSailConnection;
import org.eclipse.rdf4j.sail.SailConnection;
import org.junit.jupiter.api.Test;

class MemoryStoreBulkAddHookTest {

	@Test
	void overridingHookCannotInheritSinkOwnedBatching() {
		AtomicInteger hooks = new AtomicInteger();
		MemoryStore store = store(statement -> {
			if (hooks.incrementAndGet() % 2 == 0) {
				return true;
			}
			return false;
		});
		List<Statement> rows = List.of(statement("a"), statement("b"), statement("c"), statement("d"), statement("e"));
		store.init();
		try (SailConnection connection = store.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			connection.addStatements(rows);
			connection.commit();
			assertEquals(Set.copyOf(rows), Iterations.asSet(connection.getStatements(null, null, null, false)));
			assertEquals(rows.size(), hooks.get());
		} finally {
			store.shutDown();
		}
	}

	@Test
	void throwingHookRetainsExactlyTheAlreadyApprovedRow() {
		IllegalStateException failure = new IllegalStateException("storage row hook failed");
		MemoryStore store = store(statement -> {
			throw failure;
		});
		Statement first = statement("first");
		store.init();
		try (SailConnection connection = store.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			assertSame(failure, assertThrows(IllegalStateException.class,
					() -> connection.addStatements(List.of(first, statement("second")))));
			connection.commit();
			assertEquals(Set.of(first), Iterations.asSet(connection.getStatements(null, null, null, false)));
		} finally {
			store.shutDown();
		}
	}

	private MemoryStore store(Predicate<Statement> flushHook) {
		return new MemoryStore() {
			@Override
			protected NotifyingSailConnection getConnectionInternal() {
				return new MemoryStoreConnection(this) {
					@Override
					protected void bulkStatementAdded(Statement statement, Resource... contexts) {
						super.bulkStatementAdded(statement, contexts);
						if (flushHook.test(statement)) {
							flushUpdates();
						}
					}
				};
			}
		};
	}

	private Statement statement(String suffix) {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		return vf.createStatement(vf.createIRI("urn:hook:" + suffix), vf.createIRI("urn:p"), vf.createIRI("urn:o"));
	}
}
